// The Material icon catalogue (data/mui-icons.json, ~2,000 icons, regenerated by
// scripts/gen-mui-icons.mjs), searched on the server. Shared by the icon picker's
// route (app/api/icons/mui) and the agent's icon tools, so both find the same
// icons and store the same markup. The catalogue itself never goes to a browser.
import catalogue from "@/data/mui-icons.json";

type CatalogueIcon = { name: string; paths: { d: string; fillRule?: string; clipRule?: string; opacity?: string }[] };

const ICONS = (catalogue as { icons: CatalogueIcon[] }).icons;
export const MUI_VIEW_BOX = (catalogue as { viewBox?: string }).viewBox || "0 0 24 24";

/** "AccountCircle" → "account circle", so a plain-language query matches. */
const words = (name: string) => name.replace(/([a-z\d])([A-Z])/g, "$1 $2").toLowerCase();
// Precomputed once per process rather than per request — the catalogue never
// changes at runtime.
const INDEX = ICONS.map((i) => ({ icon: i, hay: words(i.name) }));

/** The inner markup for one icon, ready to store on an Icon record. */
function svgOf(icon: CatalogueIcon): string {
  return icon.paths
    .map((p) => {
      let a = `d="${p.d}"`;
      if (p.fillRule) a += ` fill-rule="${p.fillRule}"`;
      if (p.clipRule) a += ` clip-rule="${p.clipRule}"`;
      if (p.opacity) a += ` opacity="${p.opacity}"`;
      return `<path ${a}/>`;
    })
    .join("");
}

export type MuiMatch = { name: string; svg: string };

/** Icons matching every word of `q`, best first. An empty query lists them all. */
export function searchMuiIcons(q: string, limit: number): { total: number; icons: MuiMatch[] } {
  const query = q.trim().toLowerCase();
  let hits = INDEX;
  if (query) {
    const terms = query.split(/\s+/).filter(Boolean);
    hits = INDEX.filter((e) => terms.every((t) => e.hay.includes(t)));
    // A name that starts with the query is what the searcher usually meant
    // ("search" should lead with Search, not ManageSearch).
    hits = [...hits].sort((a, b) => {
      const as = a.hay.startsWith(query) ? 0 : 1, bs = b.hay.startsWith(query) ? 0 : 1;
      return as - bs || a.icon.name.length - b.icon.name.length || a.icon.name.localeCompare(b.icon.name);
    });
  }
  return { total: hits.length, icons: hits.slice(0, limit).map((e) => ({ name: e.icon.name, svg: svgOf(e.icon) })) };
}

/** One icon by its exact name ("Apple"), ignoring case; null when there is none. */
export function muiIconByName(name: string): MuiMatch | null {
  const n = name.trim().toLowerCase();
  const hit = ICONS.find((i) => i.name.toLowerCase() === n);
  return hit ? { name: hit.name, svg: svgOf(hit) } : null;
}
